mkdir -p fixture && cd fixture && npm init -y && npm install --save-dev jest@29 && cat > flaky.test.js << 'EOF'
const net = require('net');

function startServer(port) {
  return new Promise((resolve) => {
    const server = net.createServer();
    server.listen(port, () => resolve(server));
  });
}

async function testWithRace() {
  const server = await startServer(0);
  const port = server.address().port;
  server.close();

  // BUG: Race condition - server closed before client connects
  const client = net.createConnection({ port });
  return new Promise((resolve, reject) => {
    client.on('connect', () => resolve('connected'));
    client.on('error', (e) => reject(e));
    setTimeout(() => reject(new Error('timeout')), 100);
  });
}

test('flaky connection test', async () => {
  await testWithRace();
});
EOF
